<template>
  <!-- <dropdown :options="table_name_list" :currentElement="currentElement" :@inputValueChanges="$emit('inputValueChangesTable', currentElement)" :labelToDisplay="'table_name'" ></dropdown> -->
  <dropdown
    :options="table_name_list"
    :currentElement="currentElement"
    :labelToDisplay="$t('table_name')"
  ></dropdown>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { i18n } from 'src/boot/i18n';
import { defineComponent, ref } from 'vue';
import dropdown from './generic-dropdown-searchable.vue';
import { useWorkflowBuilderStore, useDropdownStore } from 'src/store/main';

export default defineComponent({
  name: 'table_name_list-dropdown',
  // emits: ['updateModel', 'inputValueChanges'],
  // emits: ['inputValueChangesTable'],

  components: { dropdown },
  props: {
    currentElement: {
      type: Object,
      default: {
        id: '',
        data: null,
        data_type: '',
        data_set: [],
        is_list: false,
        display_name: '',
      } as any,
    },
  },
  data() {
    return {
      optionValue: 'valueStr',
    };
  },

  methods: {
    updateModelOnLoad(currentElement: any) {
      const dropdown_store = useDropdownStore();
      dropdown.methods?.updateModelOnLoad(
        currentElement,
        dropdown_store.table_name_list,
      );
    },
  },
  setup() {
    const workflow_builder_store = useWorkflowBuilderStore();
    const { workflowModel } = storeToRefs(workflow_builder_store);

    const dropdown_store = useDropdownStore();
    const { table_name_list } = storeToRefs(dropdown_store);

    return {
      workflowModel,
      table_name_list,
    };
  },
});
</script>

