<template>
  <q-badge
    rounded
    outline
    color="grey"
    class="text-capitalize cursor-pointer q-ml-xs"
    :label="currentElement.display_name"
    v-if="false"
  >
    </q-badge>

    <q-btn 
    :size="
      workflowModel[currentElementId].badgeValue ==
      workflowModel[currentElementId].defaultValue
        ? 'xs'
        : 'md'
    "
    :flat="
      workflowModel[currentElementId].badgeValue ==
      workflowModel[currentElementId].defaultValue
        ? false
        : true
    "
    :rounded="
      workflowModel[currentElementId].badgeValue ==
      workflowModel[currentElementId].defaultValue
