      workflowModel[currentElementId].badgeValue ==
      workflowModel[currentElementId].defaultValue
        ? ''
        : 'selected-custom-badge',
      { 'custom-badge--dark': $q.dark.isActive },
    ]" 
    :color="
      workflowModel[currentElementId].badgeValue ==
      workflowModel[currentElementId].defaultValue
        ? 'custom-badge-light'
        : 'custom-badge-bold'
    "
    :label="
      getLabel(
        isDialog
          ? $t(
              $t('wf_' + workflowModel[currentElementId].defaultValue).replace(
                /^wf_/,
                '',
              ),
            )
          : $t($t('wf_' + workflowModel[currentElementId].badgeValue)).replace(
              /^wf_/,
              '',
            ),
      )
    "
    v-if="currentElement.display_name"
  >
    <q-menu
      v-if="!isDialog"
      fit
      anchor="bottom middle"
      self="top middle"
      style="
        border-radius: 10px;
        box-shadow:
          0 10px 44px 0 rgba(0, 0, 0, 0.07),
          0 2px 12px 0 rgba(0, 0, 0, 0.1),
          0 2px 4px 0 rgba(0, 0, 0, 0.04) !important;
      "
    >
      <q-icon name="arrow_drop_up" color="amber" v-if="false" />
      <div class="row no-wrap q-pa-sm q-pb-md width-320px">
          <div class="col-sm-12 col-md-12 col-lg-12">
          <component
            :is="effectiveComponentName"
            :currentElement="currentElement"
          >
            </component>
          </div>
        </div>
      </q-menu>
    </q-btn>
</template>

<script lang="ts">
