import table_column_name_right from './WorkflowComponnets/table_column_nameDropdown.vue';
import column_name_dependency from './WorkflowComponnets/table_column_nameDropdown.vue';
import result_column_name from './WorkflowComponnets/table_column_nameDropdown.vue';
import recipient from './WorkflowComponnets/generic-from-db-Dropdown.vue';
import field_status from './WorkflowComponnets/generic-from-db-Dropdown.vue';
import workflow from './WorkflowComponnets/workflowDropdown.vue';
import boolean from './WorkflowComponnets/generic-from-db-Dropdown.vue';
import tolerance_amount from './WorkflowComponnets/generic-input.vue';
