import comparison_data from './WorkflowComponnets/generic-from-db-Dropdown.vue';
import task_type from './WorkflowComponnets/generic-from-db-Dropdown.vue';
import store_data from './WorkflowComponnets/generic-from-db-Dropdown.vue';
import wf_script from './WorkflowComponnets/docOperator-promptsDropdown.vue';
import script_data from './WorkflowComponnets/docOperator-variablesDropdown.vue';
import po_column from './WorkflowComponnets/po-display-colsDropdown.vue';
import supplier_item from './WorkflowComponnets/generic-from-db-Dropdown.vue';
import supplier_type from './WorkflowComponnets/generic-from-db-Dropdown.vue';
import docoperators_run_env from './WorkflowComponnets/generic-from-db-Dropdown.vue';
import po_import_type from './WorkflowComponnets/generic-from-db-Dropdown.vue';
import po_db_column from './WorkflowComponnets/generic-from-db-Dropdown.vue';
import po_db_table from './WorkflowComponnets/generic-from-db-Dropdown.vue';
import delivery_date_type from './WorkflowComponnets/generic-from-db-Dropdown.vue';
import allowed_tolerance_days from './WorkflowComponnets/generic-from-db-Dropdown.vue';
import wf_supplier_status from './WorkflowComponnets/generic-from-db-Dropdown.vue';
import email_recipient from './WorkflowComponnets/generic-from-db-Dropdown.vue';
import email_templates from './WorkflowComponnets/emailTemplateDropdown.vue';
import variable_name from './WorkflowComponnets/WorkflowVariableDropdown.vue';
import { i18n } from 'src/boot/i18n';
import {
  resolveWorkflowVariableRef,
  badgeResolvesFromDropdownList,
} from './workflow-variable-handler';

export const componentReference = {
  time: wf_time,
  user,
  users,
  operator,
  priority,
  status,
  str,
  sub_org_id,
  event,
  cronjob,
  field_value,
  field_name,
  doc_type,
  sub_doc_type,
  math_operator,
  table: wf_table,
  tables,
  method,
  send_email,
  table_name,
  table_column_name,
  order_data,
  groups,
  table_column_name_compare,
  table_column_name_compare_to,
  table_column_name_dependency,
  table_column_name_left,
  table_column_name_right,
  column_name_dependency,
  result_column_name,
  recipient,
  field_status,
  workflow,
  boolean,
  tolerance_amount,
  tolerance_type,
  condition_result,
  master_data_table,
  operator_any_all,
  minutes,
  ignore_pending_tasks,
  export_configuration,
  region,
  date,
  decision_table,
  module,
  use_decision_table,
  assignee_type,
  trigger_docflow,
  comparison_data,
  task_type,
  store_data,
  script: wf_script,
  script_data,
  po_column,
  supplier_item,
  supplier_type,
  docoperators_run_env,
  po_import_type,
  po_db_column,
  po_db_table,
  delivery_date_type,
  allowed_tolerance_days,
  wf_supplier_status,
  email_recipient,
  email_templates,
  variable_name,
};

export default defineComponent({
  name: 'badge',
  // emits: ['onCardClick', 'removeCard', 'replaceCard'],
  mixins: [helperUtil],

  components: {
    wf_time,
    user,
    users,
    operator,
    priority,
    status,
    str,
    sub_org_id,
    event,
    cronjob,
    field_value,
    field_name,
    doc_type,
    sub_doc_type,
    math_operator,
    wf_table,
    tables,
    method,
    send_email,
    table_name,
    table_column_name,
    order_data,
    groups,
    table_column_name_compare,
    table_column_name_compare_to,
    table_column_name_dependency,
    table_column_name_left,
    table_column_name_right,
    column_name_dependency,
    result_column_name,
    recipient,
    field_status,
    workflow,
    boolean,
    tolerance_amount,
    tolerance_type,
    condition_result,
    master_data_table,
    operator_any_all,
    minutes,
    ignore_pending_tasks,
    export_configuration,
    region,
    date,
    decision_table,
    module,
    use_decision_table,
    assignee_type,
    trigger_docflow,
    comparison_data,
    task_type,
    store_data,
    wf_script,
    script_data,
    po_column,
    supplier_item,
    supplier_type,
    docoperators_run_env,
    po_import_type,
    po_db_column,
    po_db_table,
    delivery_date_type,
    allowed_tolerance_days,
    wf_supplier_status,
    email_recipient,
    email_templates,
    variable_name,
  },
  props: {
    isDialog: {
      type: Boolean,
      default: true,
    },
    variable: {
      type: String,
      default: '',
    },
    item: {
      type: Object,
    },
  },
  data() {
    return {
      showItemPanel: ref(false),
      currentElementId: ref(''),
      currentElement: ref({} as any),
    };
  },

  computed: {
    effectiveComponentName(): string {
      const name = this.currentElement?.componentName;
      const displayName = this.currentElement?.display_name;
      // Workflow variable name fields → use variable picker dropdown
      if (displayName === 'variable_name' || displayName === 'tag_name') {
        return 'variable_name';
      }
      // Partner card variables with data_set should render as dropdown
      if (name === 'str' && this.currentElement?.data_set?.length > 0) {
        return 'operator';
      }
      const resolved = name || 'str';
      // Remap reserved HTML element names to prefixed component names
      const reservedMap: Record<string, string> = {
        time: 'wf_time',
        table: 'wf_table',
        script: 'wf_script',
      };
      return reservedMap[resolved] || resolved;
    },
    // Sum of the badge-backing dropdown lists' lengths; changes when a lazily
    // loaded list populates, which the watcher below uses to re-resolve badges.
    // Optional-chained so a renamed list degrades to 0 instead of throwing.
    dropdownListsSignature(): number {
      const d = useDropdownStore();
      return (
        (d.usersList?.length ?? 0) +
        (d.groups_list?.length ?? 0) +
        (d.workflow_list?.length ?? 0) +
        (d.decision_table_list?.length ?? 0) +
        (d.export_configuration_list?.length ?? 0) +
        (d.doc_type_list?.length ?? 0) +
        (d.table_name_list?.length ?? 0) +
        (d.table_column_name_list?.length ?? 0) +
        (d.master_data_table_list?.length ?? 0) +
        (d.subOrgList?.length ?? 0) +
        (d.po_display_cols?.length ?? 0) +
        (d.email_template_list?.length ?? 0)
      );
    },
  },

  mounted() {
    this.prepareBadgeValue();
    // componentReference['suborg'].methods?.updateModelOnLoad();
  },

  watch: {
    item: {
      handler() {
        this.prepareBadgeValue();
      },
      deep: true,
    },
    // Re-resolve workflow variable refs when the variables list changes
    // (loads asynchronously, may rename, may delete).
    workflowVariables: {
      handler() {
        const dn = this.currentElement?.display_name;
        if (dn === 'variable_name' || dn === 'tag_name') {
          this.resolveWorkflowVariableBadge();
        }
      },
      deep: true,
    },
    // A lazily-loaded list arrived — re-resolve list-backed badges so their
    // label (group/user/workflow/…) backfills. Skipped for non-list badges.
    dropdownListsSignature() {
      if (badgeResolvesFromDropdownList(this.currentElement?.display_name, componentReference)) {
        this.prepareBadgeValue();
      }
    },
  },

  methods: {
    _inferVarType(): string | null {
      const cardType = (this.item?.card_type || '').toUpperCase();
      if (cardType.includes('BOOLEAN')) return 'boolean';
      if (cardType.includes('TEXT')) return 'text';
      if (cardType.includes('NUMBER')) return 'number';
      return null;
    },
    prepareBadgeValue() {
      if (this.item) {
        let text: string = this.variable.split(workflowSplitDelimiter).join('');
        Array.from(this.item.variables).forEach((variable: any) => {
          if (variable.id == text && variable.data_type) {
            this.currentElement = variable;
            variable.uuid = variable.uuid ? variable.uuid : uid();
            this.currentElementId = variable.uuid;

            // Enrich variable with context for WorkflowVariableDropdown
            const dn = variable.display_name;
            if (dn === 'variable_name' || dn === 'tag_name') {
              variable._useWfVarPrefix = dn === 'tag_name';
              variable._varTypeFilter = this._inferVarType();
            }

            this.updateModel(variable);
            if (dn === 'variable_name' || dn === 'tag_name') {
              this.resolveWorkflowVariableBadge();
            }
            return;
          }
        });
      }
    },
    // For variable_name/tag_name fields, the persisted ref is `wf_var.{id}`.
    // Look up the current variable and write its name into the badge so
    // closed-card badges stay correct across renames.
    resolveWorkflowVariableBadge() {
      const uuid = this.currentElementId;
      if (!uuid || !this.workflowModel[uuid]) return;
      const raw = this.workflowModel[uuid].value;
      const resolved = resolveWorkflowVariableRef(raw, this.workflowVariables);
      if (!resolved) return;
      if (this.workflowModel[uuid].badgeValue !== resolved.name) {
        this.workflowModel[uuid].badgeValue = resolved.name;
      }
    },
    updateModel(variable: any) {
      if (this.workflowModel.hasOwnProperty(variable.uuid)) {
        // Skip updateModelOnLoad if already resolved by logs viewer
        // (populateWorkflowModelForCard sets _resolved flag)
        const existing = this.workflowModel[variable.uuid];
        if (existing?._resolved) {
          return;
        }
        if (
          variable.data != null &&
          componentReference.hasOwnProperty(variable.display_name) &&
          (componentReference as any)[variable.display_name].methods
            ?.updateModelOnLoad
        ) {
          try {
            (componentReference as any)[
              variable.display_name
            ].methods?.updateModelOnLoad(variable);
          } catch {
            // Static method call may fail without component instance —
            // badgeValue is already set by initWorkFlowMode as fallback
          }
        }
        return;
      }
      this.workflowModel[variable.uuid] = {
        value : '',
        badgeValue : variable.display_name,
        defaultValue : variable.display_name,
        dependency_variables: variable.dependency_variables,
        is_list: variable.is_list,
      };
    },
    getLabel(label: string) {
      if (
        this.workflowModel[this.currentElementId].defaultValue == 'script_data'
      ) {
        return i18n.t(
          label
            .replace(/^wf_/, '')
            .replace(/,/g, ',\n')
            .replace(/{/g, '')
            .replace(/}/g, '')
            .replace(/:"/g, ': ')
            .replace(/"/g, ''),
        );
      }
      /* 
      try to translate with wf_ prefix first, then without
      labels are coming from the database and cannot be easily changed for existing workflows to new format with wf_
      */
      label = i18n.t(label.replace(/^wf_/, ''));
      return this.stringReplaceWithString(label, '_', ' ');
    },
  },
  setup() {
    const workflow_builder_store = useWorkflowBuilderStore();
    const { workflowModel, workflowVariables } = storeToRefs(workflow_builder_store);

    return {
      workflowModel,
      workflowVariables,
    };
  },
});
</script>

