<template>
  <dropdown
    :options="doc_operator_prompts"
    :currentElement="currentElement"
    :labelToDisplay="$t('wf_doc_operator_prompts')"
  />
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent } from 'vue';
import dropdown from './generic-dropdown-searchable.vue';
import { useDropdownStore } from 'src/store/main';

export default defineComponent({
  name: 'status-dropdown',
  components: { dropdown },
  props: {
    item: {
      type: Object,
    },
    currentElement: {
      type: Object,
      default: {
        id: '',
        data: null,
        data_type: '',
        data_set: [],
        is_list: false,
        display_name: '',
        dependency_variables: null,
      } as any,
    },
  },
  methods: {
    // Update Method should be available to prepare dropdown value on load
    updateModelOnLoad(currentElement: any) {
      const dropdown_store = useDropdownStore();
      dropdown.methods?.updateModelOnLoad(
        currentElement,
        dropdown_store.doc_operator_prompts,
      );
    },
  },
  setup() {
    const dropdown_store = useDropdownStore();
    const { doc_operator_prompts } = storeToRefs(dropdown_store);

    return {
      doc_operator_prompts,
    };
  },
});
</script>

