<template>
  <dropdown :options="wf_db_values[currentElement.uuid]" :currentElement="currentElement" :labelToDisplay="$t(currentElement?.display_name)" ></dropdown>
</template>

<script lang="ts">

import { storeToRefs } from 'pinia';
import { i18n } from 'src/boot/i18n';
import { defineComponent, ref } from 'vue';
import dropdown from './generic-dropdown-searchable.vue';
import { useDropdownStore, useWorkflowBuilderStore } from 'src/store/main';

export default defineComponent({
name: 'db-dropdown',
// emits: ['updateModel', 'inputValueChanges'],

components: { dropdown },
props: {
    currentElement: {
      type: Object,
    },
},

beforeMount() {
  if(this.currentElement) {
      this.updateModelOnLoad(this.currentElement)
    }
},

methods: {
  preparedbDropdown(db: any[]): any[] {
    const preparedData = [] as any[]
    for(let i = 0; i < db.length; i++) {
      preparedData.push({
        value: db[i],
        valueStr: db[i].toString(),
        label: this.prepareTranslation(db[i]),
      })
    }
    return preparedData;

  },
  updateModelOnLoad(currentElement: any) {
      try {
      const dropdown_store = useDropdownStore();
      const cached = dropdown_store.wf_db_values[currentElement.uuid];
      const dataSet = currentElement.data_set;
      if (dataSet && (cached == undefined || dataSet.length !== cached.length)) {
        dropdown_store.wf_db_values[currentElement.uuid] = this.preparedbDropdown(dataSet);
      }
      dropdown.methods?.updateModelOnLoad(currentElement, dropdown_store.wf_db_values[currentElement.uuid])
    } catch(err) {
      console.error(err)
    }
  },
  prepareTranslation(val: string): string {
    if (this.currentElement) {
      const display_name = this.currentElement.display_name
      if (this.no_translation_dropdowns.includes(display_name)) {
        return val
      }
      if (display_name == 'module') {
        return i18n.t('wf_module_dropdown_' + val.toLowerCase())
      }
    }

    return i18n.t(val)
  }

},
setup() {

  const workflow_builder_store = useWorkflowBuilderStore();
  const { workflowModel } = storeToRefs(workflow_builder_store);
  const dropdown_store = useDropdownStore();
  const { wf_db_values } = storeToRefs(dropdown_store);


  return {
    workflowModel,
    no_translation_dropdowns: ['method'],
    wf_db_values,
  }
},
});
</script>

