import { useWorkflowBuilderStore } from 'src/store/main';

// Suggestion sources for the SuggestiveInput type-ahead.
//
// A variable's suggestions can come from one of two places:
//   1. Values carried on the variable itself — its `data_set` (the same
//      db values the dropdown variants use). This is the default.
//   2. Values loaded on demand — e.g. document field names pooled from
//      every layout. Wire these up in LOADED_SOURCES below, keyed by the
//      variable's `display_name`.
//
// To give a new variable loaded suggestions, add an entry to
// LOADED_SOURCES; anything not listed falls back to its own `data_set`.

export interface SuggestionSource {
  // Optional one-shot loader, invoked when the input mounts.
  load?: () => void | Promise<void>;
  // Current suggestion values, read fresh each time the user types.
  getValues: () => string[];
}

const LOADED_SOURCES: Record<string, () => SuggestionSource> = {
  // Document field names, pooled across every doc type's layout.
  field_name: () => {
    const store = useWorkflowBuilderStore();
    return {
      load: () => store.loadAllDocumentFieldNames(),
      getValues: () => store.allDocumentFieldNames,
    };
  },
};

export function resolveSuggestionSource(currentElement: any): SuggestionSource {
  const loaded = LOADED_SOURCES[currentElement?.display_name];
  if (loaded) {
    return loaded();
  }
  // Fall back to the values carried on the variable (db `data_set`).
  const dataSet: unknown[] = Array.isArray(currentElement?.data_set)
    ? currentElement.data_set
    : [];
  const values = dataSet.map((value) => String(value));
  return { getValues: () => values };
}
