<template>
  <div class="row">
    <div
      class="col-sm-12 col-md-12 col-lg-12 color-93939A text-capitalize q-pb-sm"
    >
      {{ $t($t('wf_' + labelToDisplay).replace(/^wf_/, '')) }}
    </div>
    <div class="col-sm-12 col-md-12 col-lg-12">
      <q-select
        dense
        outlined
        emit-value
        map-options
        :options="filterOptions"
        :label="$t(label)"
        class="back-white"
        color="light-blue"
        :multiple="allowMultiSelection"
        use-input
        input-debounce="0"
        @filter="filterFn"
        @update:model-value="
          (new_value: string) => {
            inputValueChanges(new_value);
          }
        "
        v-model="workflowModel[currentElement!.uuid].value"
        :option-value="optionValue"
      >
      </q-select>
    </div>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useWorkflowBuilderStore } from 'src/store/main';
import { resetDependencyVariables } from 'src/pages/WorkflowBuilder/generic_card_functions';
export default defineComponent({
  name: 'generic-dropdown-searchable',
  // emits: ['updateModel', 'inputValueChanges'],

  components: {},
    props: {
    label: {
      type: String,
      default: 'please_select',
    },
    currentElement: {
      type: Object,
      default: {
        id: '',
        data: null,
        data_type: '',
        data_set: [],
        is_list: false,
        display_name: '',
      } as any,
    },
    options: {
      type: Array,
      default: [] as any,
    },
    labelToDisplay: {
      type: String,
      default: '',
    },
    optionValue: {
      type: String,
      default: 'value',
    },
  },
  data() {
    return {
      allowMultiSelection: ref(false),
      selectedElement: ref([]),
    };
  },
  beforeMount: function () {
    if (this.currentElement) {
      let val = this.workflowModel[this.currentElement.uuid].value;
      if (!val || val.length < 1) {
        this.workflowModel[this.currentElement.uuid].value = this.currentElement.is_list ? [] : '';
        this.workflowModel[this.currentElement.uuid].badgeValue = this.workflowModel[this.currentElement.uuid].defaultValue;
      }
    }
    this.filterOptions = this.options;
  },

  mounted() {
    if (this.currentElement) {
      this.allowMultiSelection = this.currentElement.is_list ? true : false;
    }
  },

  methods: {
    filterFn(val: any, update: any) {
      if (!val || [' ', ''].includes(val)) {
        update(() => {
          this.filterOptions = this.options;
        });
        this.$forceUpdate();
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.filterOptions = this.options!.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1,
        );
        this.$forceUpdate();
      });
    },
    inputValueChanges(val: any) {
      try {
        if (this.currentElement && this.filterOptions) {
          if (resetDependencyVariables(this.currentElement.componentName, val)) {
            notify.success(this.$t('wf_verify_variables'));
          }

          if (!val || val.length < 1) {
            this.workflowModel[this.currentElement.uuid].badgeValue = this.currentElement.display_name;
            return;
          }

          let foundObj: any = [] as any;

          if (this.allowMultiSelection) {
             
            foundObj = this.filterOptions.filter((row: any) =>
              val.includes(row.value.toString()),
            );
          } else {
            val = val.toString();

            foundObj = this.filterOptions.filter((row: any) => val == row.value);
          }

          const selectedItemNames = [] as any[];

          for (const selectedItem of foundObj) {
            selectedItemNames.push(selectedItem.label);
            if (this.currentElement.data_type == 'script:str') {
              let card_index = 0;
              let matched_index = null;
              this.setDocOperatorVariables(
                selectedItem,
                this.currentElement.uuid,
              );

              main_loop_index: for (let then_card of this.selectedThenCards) {
                card_index += 1;
                for (let then_variable of then_card.variables) {
                  if (then_variable.uuid == this.currentElement.uuid) {
                    matched_index = card_index;
                    break main_loop_index;
                  }
                }
              }
              if (matched_index != null) {
                for (let then_variable of this.selectedThenCards[
                  matched_index - 1
                ].variables) {
                  if (then_variable.data_type != 'script_data:dict') {
                    continue;
                  }
                  then_variable.data = null;
                  delete then_variable.badgeValue;
                  this.workflowModel[then_variable.uuid].value = '';
                  this.workflowModel[then_variable.uuid].badgeValue =
                    this.workflowModel[then_variable.uuid].defaultValue;
                  break;
                }
              }
            }
          }
          this.workflowModel[this.currentElement.uuid].badgeValue = selectedItemNames && selectedItemNames.length > 0 ? selectedItemNames.join(', ') : this.workflowModel[this.currentElement.uuid].defaultValue;
        }
      } catch(err) {
        console.error(err)
      }
    },
    updateModelOnLoad(currentElement: any, optionsList: any) {
      try {
        const newField: string = currentElement.uuid;
        let val: string = currentElement.data;
        const workflow_builder_store = useWorkflowBuilderStore();
        
        if (currentElement && currentElement.uuid && workflow_builder_store.workflowModel) {
          val = workflow_builder_store.workflowModel[currentElement.uuid] ? workflow_builder_store.workflowModel[currentElement.uuid].value : currentElement.data;
        }
        if ((!val || val.length < 1)) {
          if (workflow_builder_store.workflowModel[newField]) {
            if (typeof workflow_builder_store.workflowModel[newField].value == 'string') {
              val = workflow_builder_store.workflowModel[newField].value
            }
          } else {
            workflow_builder_store.workflowModel[newField].value = currentElement.is_list ? [] : '';
            workflow_builder_store.workflowModel[newField].badgeValue = currentElement.display_name;
            return;
          }
        }

        let foundObj: any = [] as any;
        const valArray = typeof val == 'string' ? val.split(',') : workflow_builder_store.workflowModel[newField].value;
        foundObj = optionsList.filter((row: any) =>
          valArray.includes(row.value.toString()),
        );

        const selectedItemNames = [] as any[];

        const valuesAdded = [] as string[];
        for (const selectedItem of foundObj) {
          if (!valuesAdded.includes(selectedItem.value.toString())) {
            selectedItemNames.push(selectedItem.label);
            valuesAdded.push(selectedItem.value.toString())
          }
        }
        workflow_builder_store.workflowModel[newField].badgeValue = selectedItemNames && selectedItemNames.length > 0 ? selectedItemNames.join(', ') : workflow_builder_store.workflowModel[newField].defaultValue;
      } catch(err) {
        console.error(err)
      }
    },
  },
  setup() {
    const workflow_builder_store = useWorkflowBuilderStore();
    const { workflowModel, selectedThenCards } = storeToRefs(
      workflow_builder_store,
    );

    const { setDocOperatorVariables } = useWorkflowBuilderStore();

    return {
      workflowModel,
      setDocOperatorVariables,
      selectedThenCards,
      filterOptions: [] as any,
    };
  },
});
</script>

