<template>
  <div>
    <q-select
      v-model="selectedVariable"
      :options="filteredOptions"
      dense
      outlined
      emit-value
      map-options
      option-value="id"
      option-label="name"
      :label="$t('variables')"
      @update:model-value="onSelect"
    >
      <template v-slot:option="scope">
        <q-item v-bind="scope.itemProps">
          <q-item-section avatar>
            <q-icon :name="getIcon(scope.opt.var_type)" :color="getColor(scope.opt.var_type)" size="xs" />
          </q-item-section>
          <q-item-section>
            <q-item-label>{{ scope.opt.name }}</q-item-label>
          </q-item-section>
        </q-item>
      </template>
      <template v-slot:no-option>
        <q-item>
          <q-item-section class="text-grey">
            {{ $t('no_workflow_variables') }}
          </q-item-section>
        </q-item>
      </template>
    </q-select>
  </div>
</template>

<script lang="ts">
import { defineComponent, computed } from 'vue';
import { storeToRefs } from 'pinia';
import { useWorkflowBuilderStore } from 'src/store/main';
import { getTypeConfig } from './workflowVariableUtils';
import { resolveWorkflowVariableRef } from 'src/pages/WorkflowBuilder/workflow-variable-handler';

export default defineComponent({
  name: 'WorkflowVariableDropdown',
  props: {
    currentElement: {
      type: Object,
      default: () => ({}),
    },
  },
  setup(props) {
    const store = useWorkflowBuilderStore();
    const { workflowModel, workflowVariables } = storeToRefs(store);

    const usePrefix = !!props.currentElement._useWfVarPrefix;
    const typeFilter: string | null = props.currentElement._varTypeFilter || null;

    const selectedVariable = computed<string | null>({
      get() {
        const uuid = props.currentElement.uuid;
        const raw = workflowModel.value[uuid]?.value;
        return resolveWorkflowVariableRef(raw, workflowVariables.value)?.id ?? null;
      },
      // q-select v-model writes here; onSelect persists the real value.
      set() {},
    });

    const filteredOptions = computed(() => {
      const all = workflowVariables.value || [];
      if (!typeFilter) return all;
      return all.filter((v: any) => v.var_type === typeFilter);
    });

    function getIcon(type: string): string {
      return getTypeConfig(type as any).icon;
    }

    function getColor(type: string): string {
      return getTypeConfig(type as any).color;
    }

    function onSelect(id: string) {
      const uuid = props.currentElement.uuid;
      if (!uuid) return;
      const variable = (workflowVariables.value || []).find((v: any) => v.id === id);
      const name = variable?.name ?? id;
      const val = usePrefix ? `wf_var.${id}` : id;
      workflowModel.value[uuid].value = val;
      workflowModel.value[uuid].badgeValue = name;
    }

    return {
      selectedVariable,
      filteredOptions,
      getIcon,
      getColor,
      onSelect,
    };
  },
});
</script>
