<template>
  <div class="row">
    <div
      class="col-sm-12 col-md-12 col-lg-12 color-93939A text-capitalize q-pb-sm"
    >
      {{ $t(currentElement!.display_name) }}
    </div>
    <div class="container">
      <div
        class="row justify-content-center q-mb-sm"
        v-for="(value, key) in docOperatorVariables[currentElement.uuid]"
        :key="key"
      >
        <div class="col-sm-5" style="margin-top: 10px">
          {{ key }}
        </div>
        <div
          v-if="
            docOperatorVariablesSensitive[currentElement.uuid] &&
            docOperatorVariablesSensitive[currentElement.uuid].includes(key)
          "
          class="col-sm-7"
        >
          <q-input
            outlined
            dense
            color="light-blue"
            v-model="docOperatorVariables[currentElement.uuid][key]"
            :type="showPassword[key] ? 'text' : 'password'"
            :readonly="passwordLocked[key]"
            autocomplete="off"
            @update:model-value="(val: any) => inputValueChanges(key, val)"
          >
            <template v-slot:append>
              <q-icon
                v-if="!passwordLocked[key]"
                @click="toggleShow(key)"
                :name="showPassword ? 'visibility' : 'visibility_off'"
                size="24px"
                class="cursor-pointer"
              ></q-icon>
              <f-btn
                v-if="passwordLocked[key]"
                flat
                rounded
                dense
                @click="resetPasswordValue(key)"
                :label="$t('clear')"
              />
            </template>
          </q-input>
        </div>
        <div v-else class="col-sm-7">
          <q-input
            outlined
            dense
            color="light-blue"
            v-model="docOperatorVariables[currentElement.uuid][key]"
            @update:model-value="(val: any) => inputValueChanges(key, val)"
          />
        </div>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useDropdownStore, useWorkflowBuilderStore } from 'src/store/main';
import type { dynamicObj } from 'src/pages/assets';
import { populateDocOperatorFromSavedData } from 'src/pages/WorkflowBuilder/workflow-variable-handler';

export default defineComponent({
  name: 'generic-input',
  components: {},
  props: {
    currentElement: {
      type: Object,
      default: {
        id: '',
        data: null,
        data_type: '',
        data_set: [],
        is_list: false,
        display_name: '',
      } as any,
    },
  },
  data() {
    return {
      allowMultiSelection: ref(false),
      selectedElement: ref([]),
    };
  },
  mounted() {
    this.prepareDropdownData();
    this.prepareLockedInput();
  },
  methods: {
    prepareDropdownData() {
      if (!this.currentElement) {
        return;
      }
      const curr_uuid = this.currentElement.uuid;
      const saved_data = this.currentElement.data
        ? JSON.parse(this.currentElement.data)
        : {};

      // If docOperatorVariables has no entry for this UUID (can happen when
      // UUIDs are re-assigned during load), populate it from the saved data
      // and recover sensitive/locked tracking for encrypted values.
      if (!this.docOperatorVariables[curr_uuid] || Object.keys(this.docOperatorVariables[curr_uuid]).length === 0) {
        populateDocOperatorFromSavedData(
          saved_data,
          curr_uuid,
          this.docOperatorVariables,
          this.docOperatorLockedSensitiveData,
          this.docOperatorVariablesSensitive,
        );
        return;
      }

      for (const [key, val] of Object.entries(saved_data)) {
        if (
          Object.keys(this.docOperatorVariables[curr_uuid]).includes(key) &&
          !this.docOperatorVariables[curr_uuid][key]
        ) {
          this.docOperatorVariables[curr_uuid][key] = val as string;
        }
      }
    },
    prepareLockedInput() {
      if (!this.currentElement) return;
      const uuid = this.currentElement.uuid;
      const vars = this.docOperatorVariables[uuid];
      if (!vars) return;

      for (const key of Object.keys(vars)) {
        if (
          this.docOperatorLockedSensitiveData[uuid] &&
          this.docOperatorVariablesSensitive[uuid]
        ) {
          this.passwordLocked[key] =
            this.docOperatorVariablesSensitive[uuid].includes(key) &&
            this.docOperatorLockedSensitiveData[uuid].includes(key);
        } else {
          this.passwordLocked[key] = false;
        }
        this.showPassword[key] = false;
      }
    },

    toggleShow(key: any) {
      this.showPassword[key] = this.showPassword[key] ? false : true;
    },

    inputValueChanges(key: any, val: any) {
      if (!this.currentElement) {
        return;
      }
      this.workflowModel[this.currentElement.uuid].value = JSON.stringify(
        this.docOperatorVariables[this.currentElement.uuid],
      );
      if (!val) {
        this.workflowModel[this.currentElement.uuid].badgeValue =
          this.currentElement.display_name;
        return;
      }
      const newDict = this.docOperatorVariables[this.currentElement.uuid] ? this.docOperatorVariables[this.currentElement.uuid] : {};
      newDict[key] = val;
      const dictToShow = this.getShownBadgeValues(newDict);
      this.workflowModel[this.currentElement.uuid].badgeValue =
        JSON.stringify(dictToShow);
    },
    resetPasswordValue(key: any) {
      if (this.currentElement) {
        this.docOperatorVariables[this.currentElement.uuid][key] = '';
        if (
          this.docOperatorLockedSensitiveData[
            this.currentElement.uuid
          ].includes(key)
        ) {
          const index =
            this.docOperatorLockedSensitiveData[
              this.currentElement.uuid
            ].indexOf(key);
          this.docOperatorLockedSensitiveData[this.currentElement.uuid].splice(
            index,
            1,
          );
        }
      }
      this.passwordLocked[key] = false;
      this.showPassword[key] = false;
    },

    getShownBadgeValues(newDict: dynamicObj): dynamicObj {
      if (this.currentElement) {
        let dictToShow: dynamicObj = {};
        for (let key_to_save of Object.keys(newDict)) {
          if (
            this.docOperatorVariablesSensitive[this.currentElement.uuid] &&
            this.docOperatorVariablesSensitive[
              this.currentElement.uuid
            ].includes(key_to_save)
          ) {
            dictToShow[key_to_save] = '*';
          } else {
            dictToShow[key_to_save] = newDict[key_to_save];
          }
        }
        return dictToShow;
      }
      return newDict;
    },

    updateModelOnLoad(currentElement: any) {
      if (currentElement.data) {
        const workflow_builder_store = useWorkflowBuilderStore();
        workflow_builder_store.workflowModel[currentElement.uuid].badgeValue =
          currentElement.display_name;
      }
    },
  },
  setup() {
    const workflow_builder_store = useWorkflowBuilderStore();
    const setDocOperatorVariables = useWorkflowBuilderStore();
    const {
      workflowModel,
      docOperatorVariables,
      docOperatorVariablesSensitive,
      selectedThenCards,
      docOperatorLockedSensitiveData,
    } = storeToRefs(workflow_builder_store);
    const dropdown_store = useDropdownStore();
    const { doc_operator_prompts } = storeToRefs(dropdown_store);

    return {
      workflowModel,
      docOperatorVariables,
      docOperatorVariablesSensitive,
      doc_operator_prompts,
      selectedThenCards,
      setDocOperatorVariables,
      docOperatorLockedSensitiveData,
      showPassword: ref({} as dynamicObj),
      passwordLocked: ref({} as dynamicObj),
    };
  },
});
</script>

<style scoped lang="scss"></style>
