<template>
  <dropdown
    :options="export_configuration_listFiltered"
    :currentElement="currentElement"
    :labelToDisplay="$t('export_configuration')"
    :optionValue="optionValue"
  ></dropdown>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import dropdown from './generic-dropdown-searchable.vue';
import { useWorkflowBuilderStore, useDropdownStore } from 'src/store/main';

export default defineComponent({
  name: 'export_configuration-dropdown',
  // emits: ['updateModel', 'inputValueChanges'],

  components: { dropdown },
  props: {
    currentElement: {
      type: Object,
    },
  },
  data() {
    return {
      optionValue: 'valueStr',
    };
  },

  methods: {
    updateModelOnLoad(currentElement: any) {
      const dropdown_store = useDropdownStore();
      dropdown.methods?.updateModelOnLoad(
        currentElement,
        dropdown_store.export_configuration_list,
      );
    },
  },
  setup() {
    const workflow_builder_store = useWorkflowBuilderStore();
    const { workflowModel } = storeToRefs(workflow_builder_store);

    const dropdown_store = useDropdownStore();
    const { export_configuration_list } = storeToRefs(dropdown_store);
    const export_configuration_listFiltered: any = ref(
      dropdown_store.export_configuration_list,
    );

    return {
      workflowModel,
      export_configuration_list,
      export_configuration_listFiltered,
    };
  },
});
</script>

<style scoped lang="scss"></style>
