<template>
  <dropdown
    :options="table_filtered_column_name_list"
    :currentElement="currentElement"
    :labelToDisplay="$t('wf_table_column_name')"
    :label="$t('wf_please_select_table')"
  ></dropdown>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import dropdown from './generic-dropdown-searchable.vue';
import { useWorkflowBuilderStore, useDropdownStore } from 'src/store/main';

export default defineComponent({
  name: 'status-dropdown',
  // emits: ['updateModel', 'inputValueChanges'],

  components: { dropdown },
  props: {
    item: {
      type: Object,
    },
    currentElement: {
      type: Object,
      default: {
        id: '',
        data: null,
        data_type: '',
        data_set: [],
        is_list: false,
        display_name: '',
      } as any,
    },
  },
  data() {
    return {};
  },

  // mounted() {
  //   addEventListener('inputValueChangesTable',this.TEGaugeCalculation);
  // },
  // unmounted() {
  //   removeEventListener('inputValueChangesTable',this.TEGaugeCalculation);
  // },

  beforeMount() {
    this.filterOptionsForTable();
  },

  methods: {
    // Update Method should be available to prepare dropdown value on load
    updateModelOnLoad(currentElement: any) {
      const dropdown_store = useDropdownStore();
      dropdown.methods?.updateModelOnLoad(
        currentElement,
        dropdown_store.table_column_name_list,
      );
    },

    filterOptionsForTable() {
      for (const variable_uuid in this.workflowModel) {
        if (
          this.workflowModel[variable_uuid].defaultValue == 'table_name' &&
          this.workflowModel[variable_uuid].value
        ) {
          this.table_name = this.workflowModel[variable_uuid].value;
          break;
        }
      }
      if (this.table_name) {
        this.table_filtered_column_name_list =
          this.table_column_name_list.filter(
            (v: any) => v.tables.indexOf(this.table_name) > -1,
          );
        return;
      }
      this.table_filtered_column_name_list = this.table_column_name_list;
    },
  },
  setup() {
    const workflow_builder_store = useWorkflowBuilderStore();
    const { workflowModel } = storeToRefs(workflow_builder_store);

    const dropdown_store = useDropdownStore();
    const { table_column_name_list } = storeToRefs(dropdown_store);

    return {
      workflowModel,
      table_column_name_list,

      table_filtered_column_name_list: [] as any[],
      table_name: ref(''),
    };
  },
});
</script>

