<template>
  <q-input
    dense
    v-model="workflowModel[currentElement.uuid].value"
    mask="time"
    :rules="['time']"
    @update:model-value="
      (val: any) => {
        inputValueChanges(val);
      }
    "
  >
    <template v-slot:append>
      <q-icon name="access_time" class="cursor-pointer">
        <q-popup-proxy cover transition-show="scale" transition-hide="scale">
          <q-time
            v-model="workflowModel[currentElement.uuid].value"
            color="red-8"
          >
            <div class="row items-center justify-end">
              <q-btn v-close-popup label="Close" color="red-8" flat />
            </div>
          </q-time>
        </q-popup-proxy>
      </q-icon>
    </template>
  </q-input>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useWorkflowBuilderStore } from 'src/store/main';

export default defineComponent({
  name: 'badge',
  // emits: ['onCardClick', 'removeCard', 'replaceCard'],

  components: {},
  props: {
    currentElement: {
      type: {} as any,
      default: {},
    },
  },
  data() {
    return {};
  },

  // mounted() {
  //   this.prepareBadgeValue();
  // },
  // unmounted: function () {
  //   logInfo('unmounted');
  // },

  methods: {
    inputValueChanges(val: any) {
      this.workflowModel[this.currentElement.uuid].badgeValue = val;
      logInfo('time change');
    },
    updateModelOnLoad(currentElement: any) {
      const workflow_builder_store = useWorkflowBuilderStore();
      workflow_builder_store.workflowModel[currentElement.uuid].badgeValue =
        currentElement.data;
    },
  },
  setup() {
    const workflow_builder_store = useWorkflowBuilderStore();
    const { workflowModel } = storeToRefs(workflow_builder_store);

    return {
      workflowModel,
    };
  },
});
</script>

