<template>
  <div class="row">
    <div
      class="col-sm-12 col-md-12 col-lg-12 color-93939A text-capitalize q-pb-sm"
    >
      {{ $t($t('wf_' + currentElement!.display_name).replace(/^wf_/, '')) }}
    </div>
    <div class="col-sm-12 col-md-12 col-lg-12">
      <!-- String input with type-ahead suggestions. The suggestion source
           is resolved per variable (its own db `data_set`, or a loaded
           list such as document field names — see workflowSuggestionSources).
           Suggestions surface only while typing; any typed value is
           accepted (new-value-mode), so free text always works. -->
      <q-select
        outlined
        dense
        color="light-blue"
        class="back-white"
        use-input
        fill-input
        hide-selected
        hide-dropdown-icon
        input-debounce="0"
        new-value-mode="add-unique"
        :options="suggestions"
        :model-value="workflowModel[currentElement!.uuid].value"
        @focus="userEditing = true"
        @update:model-value="onSelectValue"
        @input-value="onTypeValue"
        @filter="filterSuggestions"
      />
    </div>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, PropType } from 'vue';
import { useWorkflowBuilderStore } from 'src/store/main';
import {
  resolveSuggestionSource,
  type SuggestionSource,
} from './workflowSuggestionSources';

export default defineComponent({
  name: 'suggestive-input',
  props: {
    currentElement: {
      type: Object as PropType<any>,
      default: () => ({
        id: '',
        data: null,
        data_type: '',
        data_set: [],
        is_list: false,
        display_name: '',
      }),
    },
  },
  data() {
    return {
      suggestions: [] as string[],
      // Only honor @input-value once the user has actually focused/typed.
      // Guards against an empty input-value emitted during initial fill
      // wiping a previously-saved value on load.
      userEditing: false,
    };
  },

  mounted() {
    if (this.source.load) {
      this.source.load();
    }
  },

  methods: {
    // Single writer for the model so option-pick, free typing and the
    // load path all store the value the same way and keep the closed-card
    // badge in sync. Mirrors generic-input.vue's contract.
    setFieldValue(value: string) {
      const uuid = this.currentElement?.uuid;
      if (!uuid || !this.workflowModel[uuid]) {
        return;
      }
      const next = (value ?? '').toString();
      this.workflowModel[uuid].value = next;
      this.workflowModel[uuid].badgeValue =
        next || this.currentElement.display_name;
    },
    // Emitted when a suggestion is picked or a new value is committed
    // (Enter). Null can arrive from QSelect internals (e.g. clear) — ignore
    // it so a valid typed value isn't wiped; clears come via @input-value.
    onSelectValue(value: string | null) {
      if (value == null) {
        return;
      }
      this.setFieldValue(value);
    },
    // Emitted on every keystroke — keeps free text (including values never
    // confirmed with Enter) as the source of truth.
    onTypeValue(text: string) {
      if (!this.userEditing) {
        return;
      }
      this.setFieldValue(text ?? '');
    },
    // Suggestions are input-driven: nothing until the user types, then
    // surface source values containing the query. When there's no match we
    // abort so no empty menu pops up — the value is still accepted as typed.
    filterSuggestions(value: string, update: any, abort: any) {
      const needle = (value || '').toLowerCase().trim();
      if (!needle) {
        abort();
        return;
      }
      const matches = this.source
        .getValues()
        .filter((option: string) => option.toLowerCase().includes(needle))
        .slice(0, 20);
      if (matches.length === 0) {
        abort();
        return;
      }
      update(() => {
        this.suggestions = matches;
      });
    },
    // Called statically by badge.vue on load (componentReference) to
    // restore the badge label from the persisted value.
    updateModelOnLoad(currentElement: any) {
      if (currentElement.data) {
        const store = useWorkflowBuilderStore();
        store.workflowModel[currentElement.uuid].badgeValue =
          currentElement.data;
      }
    },
  },

  setup(props) {
    const store = useWorkflowBuilderStore();
    const { workflowModel } = storeToRefs(store);
    const source: SuggestionSource = resolveSuggestionSource(
      props.currentElement,
    );

    return {
      workflowModel,
      source,
    };
  },
});
</script>

<style scoped lang="scss"></style>
