<template>
  <dropdown
    :options="filtered_email_templates"
    :currentElement="currentElement"
    :labelToDisplay="$t(currentElement.display_name)"
  ></dropdown>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import dropdown from './generic-dropdown-searchable.vue';
import { useWorkflowBuilderStore, useDropdownStore } from 'src/store/main';
import { getVariableValueFromOtherVariableUUID } from 'src/pages/WorkflowBuilder/generic_card_functions';

export default defineComponent({
  name: 'status-dropdown',
  // emits: ['updateModel', 'inputValueChanges'],

  components: { dropdown },
  props: {
    currentElement: {
      type: Object,
      default: {
        id: '',
        data: null,
        data_type: '',
        data_set: [],
        is_list: false,
        display_name: '',
      } as any,
    },
  },
  data() {
    return {};
  },
  beforeMount() {
    this.filterOptions();
  },

  methods: {
    // Update Method should be available to prepare dropdown value on load
    updateModelOnLoad(currentElement: any) {
      const dropdown_store = useDropdownStore();
      dropdown.methods?.updateModelOnLoad(
        currentElement,
        dropdown_store.email_template_list,
      );
    },

    filterOptions() {
      this.doc_type = '';
      this.doc_condition = '';
      this.card_relation_uuid = '';
      for (const variable_uuid in this.workflowModel) {
        if (
          this.workflowModel[variable_uuid].defaultValue == 'doc_type' &&
          this.workflowModel[variable_uuid].value
        ) {
          this.card_relation_uuid = variable_uuid;
          this.doc_type = this.workflowModel[variable_uuid].value;
          break;
        }
      }
      this.doc_condition = getVariableValueFromOtherVariableUUID(
        'operator',
        this.card_relation_uuid,
      );
      if (this.doc_type && this.doc_condition) {
        if (this.doc_condition == 'eq' || this.doc_condition == 'is') {
          this.filtered_email_templates = this.email_template_list.filter(
            (v: any) => v.doc_type.indexOf(this.doc_type) > -1,
          );
        } else {
          this.filtered_email_templates = this.email_template_list.filter(
            (v: any) => v.doc_type.indexOf(this.doc_type) == -1,
          );
        }
        return;
      }
      this.filtered_email_templates = this.email_template_list;
    },
  },
  setup() {
    const workflow_builder_store = useWorkflowBuilderStore();
    const { workflowModel } = storeToRefs(workflow_builder_store);

    const dropdown_store = useDropdownStore();
    const { email_template_list } = storeToRefs(dropdown_store);

    return {
      workflowModel,
      email_template_list,
      filtered_email_templates: [] as any[],

      card_relation_uuid: ref(''),
      doc_type: ref(''),
      doc_condition: ref(''),
    };
  },
});
</script>

<style scoped lang="scss"></style>
