<template>
  <div class="row">
    <div
      class="col-sm-12 col-md-12 col-lg-12 color-93939A text-capitalize q-pb-sm"
    >
      {{ $t($t('wf_' + currentElement!.display_name).replace(/^wf_/, '')) }}
    </div>
    <div class="col-sm-12 col-md-12 col-lg-12">
      <q-input
        outlined
        dense
        color="light-blue"
        :type="inputType"
        :step="inputStep"
        @update:model-value="
          (val) => {
            inputValueChanges(val);
          }
        "
        v-model="workflowModel[currentElement!.uuid].value"
      >
      </q-input>
    </div>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useWorkflowBuilderStore } from 'src/store/main';

export default defineComponent({
  name: 'generic-input',
  // emits: ['updateModel', 'inputValueChanges'],

  components: {},
  props: {
    currentElement: {
      type: Object,
      default: {
        id: '',
        data: null,
        data_type: '',
        data_set: [],
        is_list: false,
        display_name: '',
      } as any,
    },
  },
  data() {
    return {
      allowMultiSelection: ref(false),
      selectedElement: ref([]),
    };
  },

  computed: {
    inputType(): 'text' | 'number' {
      const dt = (this.currentElement?.data_type || '').toLowerCase();
      if (dt.includes('int') || dt.includes('float') || dt === 'value') {
        // Fall back to text if the existing value isn't a valid number
        const existing = this.currentElement?.data;
        if (existing != null && existing !== '' && isNaN(Number(existing))) {
          return 'text';
        }
        return 'number';
      }
      return 'text';
    },
    inputStep(): string | undefined {
      const dt = (this.currentElement?.data_type || '').toLowerCase();
      if (dt.includes('float')) return 'any';
      if (dt.includes('int')) return '1';
      if (dt === 'value') return 'any';
      return undefined;
    },
  },

  methods: {
    inputValueChanges(val: any) {
      if (this.currentElement) {
        if (!val) {
          this.workflowModel[this.currentElement.uuid].badgeValue =
            this.currentElement.display_name;
          return;
        }

        this.workflowModel[this.currentElement.uuid].badgeValue = val;
      }
    },
    updateModelOnLoad(currentElement: any) {
      if (currentElement.data) {
        const workflow_builder_store = useWorkflowBuilderStore();
        workflow_builder_store.workflowModel[currentElement.uuid].badgeValue =
          currentElement.data;
      }
    },
  },
  setup() {
    const workflow_builder_store = useWorkflowBuilderStore();
    const { workflowModel } = storeToRefs(workflow_builder_store);

    return {
      workflowModel,
    };
  },
});
</script>

<style scoped lang="scss"></style>
